// Rotates the topic from the 30-day calendar
const cal=[
 {pillar:'city_life',topic:'Bandra mein 200 rupaye mein best coffee'},
 {pillar:'fashion_on_budget',topic:'ek kurti teen looks'},
 {pillar:'self_care_habits',topic:'raat ko phone side rakhne ka 5 minute rule'},
 {pillar:'money_tips',topic:'salary aate hi 3 hisse'},
 {pillar:'relatable_humour',topic:'monday morning ka sach'}
];
const day=Math.floor(Date.now()/86400000);
const row=cal[day%cal.length];
return [{json:{...row, day}}];

