const raw=$json.candidates[0].content.parts[0].text;
const s=JSON.parse(raw.replace(/```json|```/g,''));
return [{json:{...s, scenePrompt:`Using the reference image as the exact identity of the woman, keep her face 100% unchanged. SCENE: ${s.scene}. OUTFIT: ${s.outfit}. EXPRESSION: ${s.expression}. CAMERA: ${s.camera}. LIGHT: ${s.light}. GRADE: ${s.grade}. Photorealistic phone-camera realism, visible skin texture, no retouching, vertical 9:16, no text, no watermark.`}}];

// fal queue: poll the status url, then return the video url
const j=$json;
return [{json:{requestId:j.request_id,statusUrl:j.status_url,responseUrl:j.response_url}}];

// Optional: hand the video to Blotato/Buffer for scheduling instead of direct IG
const url=$json.video?.url || $json.video_url || $json.url;
if(!url) throw new Error('No video url in fal response: '+JSON.stringify($json).slice(0,300));
return [{json:{videoUrl:url}}];
